// spec is the Swagger 2.0 document generated by swag into docs/.
var (
	specOnce sync.Once
	spec     map[string]any
	specErr  error
)

func loadSpec(t *testing.T) map[string]any {
	t.Helper()
	specOnce.Do(func() { specErr = json.Unmarshal([]byte(docs.SwaggerInfo.ReadDoc()), &spec) })
	if specErr != nil {
		t.Fatalf("docs/docs.go does not hold valid JSON: %v", specErr)
	}
	return spec
}

func m(v any) map[string]any { x, _ := v.(map[string]any); return x }

func operation(t *testing.T, method, path string) map[string]any {
	return m(m(m(loadSpec(t)["paths"])[path])[strings.ToLower(method)])
}

func resolveRef(t *testing.T, ref string) map[string]any {
	var cur any = loadSpec(t)
	for _, seg := range strings.Split(strings.TrimPrefix(ref, "#/"), "/") {
		cur = m(cur)[seg]
	}
	if cur == nil {
		t.Fatalf("unresolved $ref %s", ref)
	}
	return m(cur)
}

// checkContract validates a live response against the Swagger doc. Paths
// the doc does not describe (unknown routes, Swagger UI assets) are
// skipped, but a status code the doc does not list for a described path
// fails.
func checkContract(t *testing.T, method, path string, r *Result) {
	t.Helper()
	op := operation(t, method, path)
	if op == nil {
		return
	}
	resp, listed := m(op["responses"])[strconv.Itoa(r.Status)]
	if !listed {
		t.Errorf("contract: %s %s returned HTTP %d, which the Swagger doc does not list", method, path, r.Status)
		return
	}
	schema := m(m(resp)["schema"])
	if schema == nil || r.JSON == nil {
		return
	}
	var doc any
	if err := json.Unmarshal(r.Raw, &doc); err != nil {
		t.Errorf("contract: %s %s: body is not JSON: %v", method, path, err)
		return
	}
	for _, e := range validate(t, schema, doc, "$") {
		t.Errorf("contract: %s %s HTTP %d: %s\nbody: %s", method, path, r.Status, e, r.Raw)
	}
}

func nullable(s map[string]any) bool { return s["x-nullable"] == true }

// validate checks v against the schema rules swag emits: $ref, allOf,
// type, x-nullable, enum, required, properties, additionalProperties,
// items, and the date-time and uri formats. Properties the schema does not
// list are errors unless additionalProperties allows them, so the code
// cannot return fields the doc does not describe.
func validate(t *testing.T, s map[string]any, v any, at string) []string {
	if ref, ok := s["$ref"].(string); ok {
		if v == nil && nullable(s) {
			return nil
		}
		return validate(t, resolveRef(t, ref), v, at)
	}
	var errs []string
	if all, ok := s["allOf"].([]any); ok {
		if v == nil && nullable(s) {
			return nil
		}
		for _, sub := range all {
			errs = append(errs, validate(t, m(sub), v, at)...)
		}
		return errs
	}
	if v == nil {
		if nullable(s) || s["type"] == nil {
			return nil
		}
		return []string{at + ": null is not allowed (add extensions:\"x-nullable\")"}
	}
	if enum, ok := s["enum"].([]any); ok {
		found := false
		for _, e := range enum {
			if fmt.Sprint(e) == fmt.Sprint(v) {
				found = true
			}
		}
		if !found {
			errs = append(errs, fmt.Sprintf("%s: %v is not one of %v", at, v, enum))
		}
	}
	switch s["type"] {
	case "object":
		obj, ok := v.(map[string]any)
		if !ok {
			return append(errs, at+": want object")
		}
		props := m(s["properties"])
		for _, r := range asList(s["required"]) {
			if _, ok := obj[r]; !ok {
				errs = append(errs, fmt.Sprintf("%s: missing required %q", at, r))
			}
		}
		keys := make([]string, 0, len(obj))
		for k := range obj {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			if ps, ok := props[k]; ok {
				errs = append(errs, validate(t, m(ps), obj[k], at+"."+k)...)
				continue
			}
			switch ap := s["additionalProperties"].(type) {
			case map[string]any:
				errs = append(errs, validate(t, ap, obj[k], at+"."+k)...)
			case bool:
				if !ap {
					errs = append(errs, fmt.Sprintf("%s: unexpected property %q", at, k))
				}
			default:
				errs = append(errs, fmt.Sprintf("%s: property %q is not in the Swagger doc", at, k))
			}
		}
	case "array":
		arr, ok := v.([]any)
		if !ok {
			return append(errs, at+": want array")
		}
		if items := m(s["items"]); items != nil {
			for i, it := range arr {
				errs = append(errs, validate(t, items, it, fmt.Sprintf("%s[%d]", at, i))...)
			}
		}
	case "string":
		str, ok := v.(string)
		if !ok {
			return append(errs, fmt.Sprintf("%s: want string, got %T", at, v))
		}
		switch s["format"] {
		case "date-time":
			if _, err := time.Parse(time.RFC3339, str); err != nil {
				errs = append(errs, fmt.Sprintf("%s: %q is not date-time", at, str))
			}
		case "uri":
			if u, err := url.Parse(str); err != nil || !u.IsAbs() {
				errs = append(errs, fmt.Sprintf("%s: %q is not an absolute URI", at, str))
			}
		}
	case "integer":
		if n, ok := v.(float64); !ok || n != float64(int64(n)) {
			errs = append(errs, fmt.Sprintf("%s: want integer, got %v", at, v))
		}
	case "boolean":
		if _, ok := v.(bool); !ok {
			errs = append(errs, fmt.Sprintf("%s: want boolean, got %T", at, v))
		}
	}
	return errs
}

func asList(v any) []string {
	xs, _ := v.([]any)
	out := make([]string, 0, len(xs))
	for _, x := range xs {
		out = append(out, fmt.Sprint(x))
	}
	return out
}

// TestSwaggerExamplesMatchTypes checks every property example in the doc
// against its own type and enum, so annotations cannot drift silently.
func TestSwaggerExamplesMatchTypes(t *testing.T) {
	sp := loadSpec(t)
	if sp["swagger"] != "2.0" {
		t.Fatalf("swagger version = %v", sp["swagger"])
	}
	count := 0
	for name, def := range m(sp["definitions"]) {
		for prop, ps := range m(m(def)["properties"]) {
			if ex, ok := m(ps)["example"]; ok {
				count++
				for _, e := range validate(t, m(ps), ex, name+"."+prop) {
					t.Error(e)
				}
			}
		}
	}
	if count < 20 {
		t.Fatalf("only %d examples found; struct example tags were lost", count)
	}
}

// TestContractListsAllFailureCodes keeps the error.code description and
// the code table in sync.
func TestContractListsAllFailureCodes(t *testing.T) {
	desc := fmt.Sprint(m(m(resolveRef(t, "#/definitions/ExtractError")["properties"])["code"])["description"])
	for _, c := range diagnose.Codes() {
		if !strings.Contains(desc, c) {
			t.Errorf("failure code %s is not listed in the ExtractError.code comment", c)
		}
	}
}

// TestSwaggerDocsUpToDate regenerates the docs with swag and fails when
// docs/ was not regenerated after an annotation or type change.
func TestSwaggerDocsUpToDate(t *testing.T) {
	swag, err := exec.LookPath("swag")
	if err != nil {
		t.Skip("swag is not installed: go install github.com/swaggo/swag/cmd/swag@latest")
	}
	out := t.TempDir()
	cmd := exec.Command(swag, "init", "--parseInternal", "-g", "cmd/server/main.go", "-o", out, "--outputTypes", "json")
	cmd.Dir = filepath.Join("..", "..")
	if b, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("swag init: %v\n%s", err, b)
	}
	fresh, err := os.ReadFile(filepath.Join(out, "swagger.json"))
	must(t, err)
	committed, err := os.ReadFile(filepath.Join("..", "..", "docs", "swagger.json"))
	must(t, err)
	if !bytes.Equal(bytes.TrimSpace(fresh), bytes.TrimSpace(committed)) {
		t.Fatal("docs/ is stale. Run: swag init --parseInternal -g cmd/server/main.go -o docs")
	}
}

// TestSwaggerServedDoc checks /swagger/doc.json serves the generated doc.
func TestSwaggerServedDoc(t *testing.T) {
	e := Start(t, Options{Env: opsEnv(t)})
	r := e.Get("/swagger/doc.json", map[string]string{"Authorization": opsAuthHeader()})
	var served, file map[string]any
	if r.Status != 200 || json.Unmarshal(r.Raw, &served) != nil {
		t.Fatalf("doc.json: %s", r)
	}
	raw, err := os.ReadFile(filepath.Join("..", "..", "docs", "swagger.json"))
	must(t, err)
	must(t, json.Unmarshal(raw, &file))
	for _, k := range []string{"paths", "definitions", "securityDefinitions"} {
		a, _ := json.Marshal(served[k])
		b, _ := json.Marshal(file[k])
		if !bytes.Equal(a, b) {
			t.Errorf("served %s differs from docs/swagger.json", k)
		}
	}
}
